+
+class CustomerRepositoryFilterTest {
+
+    private final QueryLog queryLog = new QueryLog();
+    private final CustomerRepository repository = new CustomerRepository(queryLog);
+
+    @Test
+    void nameTermsCanMatchEitherNameAndIgnoreTermOrder() {
+        assertEquals(2, repository.count("ada aal", Set.of()));
+        assertEquals(2, repository.count("aal ada", Set.of()));
+        assertEquals(2, repository.count("  ADA \t aal  ", Set.of()));
+        assertEquals(0, repository.count("ada virtanen", Set.of()));
+    }
+
+    @Test
+    void nameMatchingIgnoresCaseAndAccents() {
+        assertEquals(15, repository.count("makinen", Set.of()));
+        assertEquals(repository.count("makinen", Set.of()), repository.count("MAKINEN", Set.of()));
+        assertEquals(repository.count("makinen", Set.of()), repository.count("mäkinen", Set.of()));
+        assertEquals(repository.count("josephine", Set.of()), repository.count("Joséphine", Set.of()));
+    }
+
+    @Test
+    void nameAndStatusFiltersAreCombinedAndLogged() {
+        queryLog.clear();
+
+        List<Long> activeAdaAaltonens = repository
+                .findAll(0, CustomerRepository.MAX_PAGE_SIZE, List.of(new CustomerSort("id", true)),
+                        "ada aal", Set.of(CustomerStatus.ACTIVE))
+                .stream()
+                .map(customer -> customer.id())
+                .toList();
+        int count = repository.count("ada aal", Set.of(CustomerStatus.ACTIVE));
+
+        assertEquals(List.of(1000L), activeAdaAaltonens);
+        assertEquals(1, count);
+        assertEquals(1, queryLog.pageQueries().size());
+        assertEquals(List.of(1), queryLog.countQueries());
+    }
